def get_row(lst, x):
    result = []
    for row_idx, row in enumerate(lst):
        indices = [col_idx for col_idx, val in enumerate(row) if val == x]
        # Sort column indices in descending order as per requirement
        indices.sort(reverse=True)
        for col_idx in indices:
            result.append((row_idx, col_idx))
    return result
